<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#222}h1{font-size:18px}h2{font-size:13px;margin-top:20px;border-bottom:1px solid #bbb;padding-bottom:4px}table{width:100%;border-collapse:collapse}th,td{padding:5px;border:1px solid #ccc;text-align:left}.right{text-align:right}.bad{color:#b91c1c}.warn{color:#a16207}.page-break{page-break-before:always}</style></head><body>
<h1>Payroll Audit Pack</h1><p><strong>{{ $payRun->company?->name }}</strong><br>Pay run: {{ $payRun->unique_no ?: '#'.$payRun->id }}<br>Period: {{ $payRun->period_start->format('Y-m-d') }} to {{ $payRun->period_end->format('Y-m-d') }}<br>Status: {{ ucfirst($payRun->status) }} / Approval: {{ ucfirst($payRun->approval_status) }}</p>
<h2>Control Summary</h2><table><tr><th>Preflight</th><th>Blockers</th><th>Warnings</th><th>Journal Debit</th><th>Journal Credit</th></tr><tr><td>{{ ucfirst($preflight['status']) }}</td><td>{{ $preflight['summary']['blockers'] }}</td><td>{{ $preflight['summary']['warnings'] }}</td><td class="right">{{ number_format($preflight['journal']['debit'],2) }}</td><td class="right">{{ number_format($preflight['journal']['credit'],2) }}</td></tr></table>
<h2>Payslips</h2><table><tr><th>Employee</th><th>Gross</th><th>Deductions</th><th>Net</th><th>YTD Net</th></tr>@foreach($payRun->payslips as $p)<tr><td>{{ $p->employee?->full_name }}</td><td class="right">{{ number_format($p->gross_earnings,2) }}</td><td class="right">{{ number_format($p->total_deductions,2) }}</td><td class="right">{{ number_format($p->net_pay,2) }}</td><td class="right">{{ number_format($p->ytd_net,2) }}</td></tr>@endforeach</table>
<h2>Preflight Findings</h2><table><tr><th>Group</th><th>Severity</th><th>Finding</th></tr>@foreach($preflight['checks'] as $c)<tr><td>{{ $c['group'] }}</td><td>{{ $c['overridden']?'Reviewed':ucfirst($c['severity']) }}</td><td>{{ $c['message'] }} @if($c['override_reason']) Reason: {{ $c['override_reason'] }} @endif</td></tr>@endforeach</table>
<div class="page-break"></div><h2>Ledger Entries</h2><table><tr><th>Reference</th><th>Account</th><th>Description</th><th>Debit</th><th>Credit</th></tr>@foreach($transactions as $t)<tr><td>{{ $t->unique_no }}</td><td>{{ $t->account?->name }}</td><td>{{ $t->description }}</td><td class="right">{{ number_format($t->debit,2) }}</td><td class="right">{{ number_format($t->credit,2) }}</td></tr>@endforeach</table>
<h2>Variance Explanations</h2><table><tr><th>Employee</th><th>Explanation</th></tr>@forelse($comments as $c)<tr><td>{{ $c->employee?->full_name }}</td><td>{{ $c->comment }}</td></tr>@empty<tr><td colspan="2">No explanations recorded.</td></tr>@endforelse</table>
<h2>Liability Schedule</h2><table><tr><th>Deduction</th><th>Recognized</th><th>Paid</th><th>Outstanding</th></tr>@foreach($liabilities as $l)<tr><td>{{ $l['name'] }}</td><td class="right">{{ number_format($l['amount'],2) }}</td><td class="right">{{ number_format($l['paid'],2) }}</td><td class="right">{{ number_format($l['amount']-$l['paid'],2) }}</td></tr>@endforeach</table>
<h2>Employee Advance Reconciliation</h2><table><tr><th>Employee</th><th>Advance</th><th>Remaining</th><th>Start</th></tr>@forelse($advances as $a)<tr><td>{{ $a->employee?->full_name }}</td><td class="right">{{ number_format($a->amount,2) }}</td><td class="right">{{ number_format($a->remaining_amount,2) }}</td><td>{{ optional($a->recovery_start_date)->format('Y-m-d') }}</td></tr>@empty<tr><td colspan="4">No outstanding advances for payroll employees.</td></tr>@endforelse</table>
<h2>Approval Evidence</h2><p>Created by: {{ $payRun->createdBy?->name ?? $payRun->created_by }}<br>Approved by: {{ $payRun->approvedBy?->name ?? $payRun->approved_by }}<br>Approved at: {{ $payRun->approved_at }}<br>Posted at: {{ $payRun->accounting_posted_at }}</p>
</body></html>
